"""Development-only assembler; the runtime imports generated bytes directly."""
from pathlib import Path
from keystone import Ks,KS_ARCH_X86,KS_MODE_32
root=Path(__file__).resolve().parents[1]
p=root/'docs/relation_sort_core.asm'
raw=bytes(Ks(KS_ARCH_X86,KS_MODE_32).asm('\n'.join(line.split(';')[0] for line in p.read_text().splitlines()))[0])
for magic in ('11111111','22222222','df9b5713','44444444'):assert raw.count(bytes.fromhex(magic))==1
assert len(raw)<0x1000
(root/'app/graph_sort_core.py').write_text('"""Generated from docs/relation_sort_core.asm. No runtime assembler required."""\nCORE=bytes.fromhex(\n'+''.join('    '+repr(raw[i:i+32].hex())+'\n' for i in range(0,len(raw),32))+')\n','utf8')
print(len(raw),'bytes')
